import { PyTuple, PyFrozenSet, PyBytes, PyComplex, PyRange, PyDict,
  pythonEquals, pythonLessThan, isNegativeZero, pythonFloatRepr, pythonIntLike } from '/output/pytypes.mjs';

const assert = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); process.exit(1); } };

// PyDict key collapsing
const d = new PyDict([[true, 'a']]);
d.set(1, 'b'); d.set(1.0, 'c');
assert(d.getEntries().length === 1, 'True/1/1.0 collapse');
assert(d.getEntries()[0][1] === 'c', 'value replaced');
assert(d.getEntries()[0][0] === true, 'original key kept');
d.set(false, 'x'); d.set(0, 'y'); d.set(0.0, 'z');
assert(d.getEntries().length === 2 && d.getEntries()[1][1] === 'z', 'False/0/0.0 collapse');
d.set(new PyTuple([1, 'a']), 't1'); d.set(new PyTuple([1.0, 'a']), 't2');
assert(d.getEntries().length === 3 && d.getEntries()[2][1] === 't2', 'equal tuples collapse');
d.set('k', 'v'); assert(d.getEntries().length === 4, 'distinct key appended');
d.set(NaN, 1); d.set(NaN, 2);
assert(d.getEntries().length === 6, 'NaN keys never collapse');

// equality
assert(pythonEquals(1, true), '1 == True');
assert(!pythonEquals(NaN, NaN), 'NaN != NaN');
assert(pythonEquals(-0, 0), '-0 == 0');
assert(pythonEquals([1, [2, 'x']], [1.0, [2, 'x']]), 'nested lists');
assert(pythonEquals(new PyTuple([1]), new PyTuple([true])), 'tuple bool/int');
assert(!pythonEquals([1], new PyTuple([1])), 'list != tuple');
assert(pythonEquals(new PyBytes(new Uint8Array([1,2])), new PyBytes(new Uint8Array([1,2]))), 'bytes equal');
assert(!pythonEquals(new PyBytes(new Uint8Array([1,2])), new PyBytes(new Uint8Array([1,3]))), 'bytes unequal');
assert(pythonEquals(new PyComplex(1, 0), 1), 'complex == number');
assert(pythonEquals(new PyFrozenSet([1, 1.0, 'a']), new PyFrozenSet(['a', true])), 'frozenset dedupe+equal');
assert(pythonEquals(new PyDict([['a', 1]]), new PyDict([['a', 1.0]])), 'dict equal');

// less than
assert(pythonLessThan(false, true) && pythonLessThan(0, 1) && pythonLessThan(1, 1.5), 'num lt');
assert(pythonLessThan('abc', 'abd') && !pythonLessThan('ab', 'ab') && pythonLessThan('ab', 'aba'), 'str lt');
assert(pythonLessThan([1, 2], [1, 3]) && pythonLessThan([1], [1, 0]) && !pythonLessThan([1, 2], [1, 2]), 'list lex');
assert(pythonLessThan(new PyTuple([1]), new PyTuple([2])), 'tuple lex');
// code-point comparison: U+10000 > U+FFFF even though UTF-16 first unit 0xD800 < 0xFFFF
assert(!pythonLessThan('\u{10000}', '\uFFFF') && pythonLessThan('\uFFFF', '\u{10000}'), 'code point compare');
let threw = false;
try { pythonLessThan(1, 'a'); } catch (e) { threw = e instanceof TypeError; }
assert(threw, 'mixed types TypeError');
threw = false;
try { pythonLessThan([1], new PyTuple([1])); } catch (e) { threw = e instanceof TypeError; }
assert(threw, 'list vs tuple TypeError');
assert(!pythonLessThan(NaN, 1) && !pythonLessThan(1, NaN), 'NaN comparisons false');

// isNegativeZero / pythonIntLike
assert(isNegativeZero(-0) && !isNegativeZero(0) && !isNegativeZero(-1), 'isNegativeZero');
assert(pythonIntLike(true) && pythonIntLike(3) && pythonIntLike(3.0) && !pythonIntLike(3.5)
  && !pythonIntLike(NaN) && !pythonIntLike(Infinity) && !pythonIntLike('3'), 'pythonIntLike');

// float repr
const cases = [
  [0, '0.0'], [-0, '-0.0'], [1, '1.0'], [-2.5, '-2.5'], [0.1, '0.1'],
  [1e15, '1000000000000000.0'], [1e16, '1e+16'], [1.5e16, '1.5e+16'],
  [1e-4, '0.0001'], [1e-5, '1e-05'], [1.234e-7, '1.234e-07'],
  [1e100, '1e+100'], [1e-100, '1e-100'], [5e-324, '5e-324'],
  [1e21, '1e+21'], [123456.789, '123456.789'], [2.0, '2.0'],
  [Infinity, 'inf'], [-Infinity, '-inf'], [NaN, 'nan'],
  [0.30000000000000004, '0.30000000000000004'],
];
for (const [v, expected] of cases) {
  const got = pythonFloatRepr(v);
  assert(got === expected, 'repr(' + v + ') = ' + got + ' expected ' + expected);
}
console.log('ALL TESTS PASSED');
