assert(pythonLessThan(false, 1n) && pythonLessThan(0n, true), 'bool vs bigint');
assert(pythonLessThan([1n, 'a'], [2, 'a']) && !pythonLessThan([1n], [1]), 'sequences with bigint');

// --- dict/set collapsing across bool/BigInt/Number ---
const d = new PyDict([[1n, 'big']]);
d.set(1, 'int'); d.set(1.0, 'float'); d.set(true, 'bool');
assert(d.getEntries().length === 1 && d.getEntries()[0][0] === 1n && d.getEntries()[0][1] === 'bool', 'dict: 1n/1/1.0/true collapse');
d.set(0n, 'z'); d.set(false, 'f'); d.set(0.0, 'fl');
assert(d.getEntries().length === 2 && d.getEntries()[1][1] === 'fl', 'dict: 0n/0/false collapse');
d.set(9007199254740993n, 'big');
d.set(9007199254740992, 'rounded');
assert(d.getEntries().length === 4, 'dict: 2^53+1 bigint and double 2^53 are distinct keys');
const s = new PySet([1n]);
s.add(1); s.add(1.0); s.add(true);
assert(s.getEntries().length === 1, 'PySet: 1n/1/1.0/true collapse');
s.add(0n); s.add(false);
assert(s.getEntries().length === 2, 'PySet: 0n/false collapse');
assert(pythonEquals(new PySet([1n, 2]), new PyFrozenSet([true, 2.0])), 'set equality across numeric kinds');

// --- pythonIntLike / typeName via error messages ---
assert(pythonIntLike(1n) && pythonIntLike(-5n) && pythonIntLike(true)
  && pythonIntLike(3.0) && !pythonIntLike(3.5) && !pythonIntLike(Infinity), 'pythonIntLike bigint');
let msg = '';
try { pythonLessThan('a', 1n); } catch (e) { msg = e.message; }
assert(msg.includes(\"'int'\") && msg.includes(\"'str'\"), 'typeName bigint -> int: ' + msg);
msg = '';
try { pythonLessThan(1.5, 'a'); } catch (e) { msg = e.message; }
assert(msg.includes(\"'float'\"), 'typeName nonintegral -> float');

// --- regression sweep ---
assert(!pythonEquals(NaN, NaN) && pythonEquals([1, [2]], [1.0, [2]]), 'regression equals');
assert(pythonLessThan('\uFFFF', '\u{10000}'), 'regression codepoint lt');
assert(pythonFloatRepr(1e16) === '1e+16' && pythonFloatRepr(-0) === '-0.0' && pythonFloatRepr(2) === '2.0', 'regression repr');
assert(isNegativeZero(-0) && !isNegativeZero(0), 'regression -0');
assert(pythonEquals(new PyComplex(1, 0), 1) && pythonEquals(new PyComplex(2, 0), 2n), 'complex vs number/bigint');
